def optimize_inner(self, operations, app_label):
    """Inner optimization loop."""
    new_operations = []
    for i, operation in enumerate(operations):
        right = True  # Should we reduce on the right or on the left.
        # Compare it to each operation after it
        for j, other in enumerate(operations[i + 1 :]):
            result = operation.reduce(other, app_label)
            if isinstance(result, list):
                in_between = operations[i + 1 : i + j + 1]
                if right:
                    new_operations.extend(in_between)
                    new_operations.extend(result)
                elif all(op.reduce(other, app_label) is True for op in in_between):
                    # Perform a left reduction if all of the in-between
                    # operations can optimize through other.
                    new_operations.extend(result)
                    new_operations.extend(in_between)
                else:
                    # Otherwise keep trying.
                    new_operations.append(operation)
                    break
                new_operations.extend(operations[i + j + 2 :])
                return new_operations
            elif not result:
                # Can't perform a right reduction.
                right = False
        else:
            new_operations.append(operation)
    return new_operations

def _has_top_level_pipe(regex: str) -> bool:
    """Whether ``regex`` contains a ``|`` at the top level.

    A top-level ``|`` is one that is not backslash-escaped, not inside a
    ``(...)`` group, and not inside a ``[...]`` character class -- i.e. a real
    alternation between separate messages rather than an inline ``(a|b)``.
    """
    depth = 0
    in_character_class = False
    index = 0
    while index < len(regex):
        char = regex[index]
        if char == "\\":
            index += 2
            continue
        if in_character_class:
            if char == "]":
                in_character_class = False
        elif char == "[":
            in_character_class = True
        elif char == "(":
            depth += 1
        elif char == ")":
            depth = max(0, depth - 1)
        elif char == "|" and depth == 0:
            return True
        index += 1
    return False

@property
def cookies(self) -> dict[str, http.cookies.Morsel]:
    """A dictionary of ``http.cookies.Morsel`` objects."""
    if not hasattr(self, "_cookies"):
        self._cookies: http.cookies.SimpleCookie = http.cookies.SimpleCookie()
        if "Cookie" in self.headers:
            try:
                parsed = parse_cookie(self.headers["Cookie"])
            except Exception:
                pass
            else:
                for k, v in parsed.items():
                    try:
                        self._cookies[k] = v
                    except Exception:
                        # SimpleCookie imposes some restrictions on keys;
                        # parse_cookie does not. Discard any cookies
                        # with disallowed keys.
                        pass
    return self._cookies

