        select(Vertex),
        "SELECT vertices.id, vertices.x1, vertices.y1, vertices.x2, "
        "vertices.y2 FROM vertices",
    )

    decl_base.metadata.create_all(connection)
    s = Session(connection)
    hv = Vertex(start=Point(1, 2), end=Point(3, 4))
    s.add(hv)
