@staticmethod
def _convert_categorical(from_frame: DataFrame) -> DataFrame:
    """
    Emulate the categorical casting behavior we expect from roundtripping.
    """
    for col in from_frame:
        ser = from_frame[col]
        if isinstance(ser.dtype, CategoricalDtype):
            cat = ser._values.remove_unused_categories()
            if cat.categories.dtype == object:
                categories = pd.Index._with_infer(
                    cat.categories._values, copy=False
                )
                cat = cat.set_categories(categories)
            elif cat.categories.dtype == "string" and len(cat.categories) == 0:
                # if the read categories are empty, it comes back as object dtype
                categories = cat.categories.astype(object)
                cat = cat.set_categories(categories)
            from_frame[col] = cat
    return from_frame

@testing.combinations((True,), (False,), argnames="create_dependency")
@testing.combinations((True,), (False,), argnames="configure_at_once")
def test_before_mapper_configured_event(
    self, create_dependency, configure_at_once
):
    """Test [ticket:4397].

    This event is intended to allow a specific mapper to be skipped during
    the configure step, by returning a value of
    :attr:`.orm.interfaces.EXT_SKIP` which means the mapper will be skipped
    within this configure run.    The "new mappers" flag will remain set in
    this case and the configure operation will occur again.

    This event, and its return value, make it possible to query one base
    while a different one still needs configuration, which cannot be
    completed at this time.
    """

    User, users = self.classes.User, self.tables.users
    ump = self.mapper_registry.map_imperatively(User, users)

    AnotherBase = declarative_base()

    class Animal(AnotherBase):
        __tablename__ = "animal"
        species = Column(String(30), primary_key=True)
        __mapper_args__ = dict(
            polymorphic_on="species", polymorphic_identity="Animal"
        )
        if create_dependency:
            user_id = Column("user_id", ForeignKey(users.c.id))

    if not configure_at_once:
        # Register the first classes and create their Mappers:
        configure_mappers()

        unconfigured = list(mapperlib._unconfigured_mappers())
        eq_(0, len(unconfigured))

    if create_dependency:
        ump.add_property("animal", relationship(Animal))

    # Declare a subclass, table and mapper, which refers to one that has
    # not been loaded yet (Employer), and therefore cannot be configured:
    class Mammal(Animal):
        nonexistent = relationship("Nonexistent")
        __mapper_args__ = {"polymorphic_identity": "mammal"}

    # These new classes should not be configured at this point:
    unconfigured = list(mapperlib._unconfigured_mappers())

    if configure_at_once:
        eq_(3, len(unconfigured))
    else:
        eq_(1, len(unconfigured))

    # Now try to query User, which is internally consistent. This query
    # fails by default because Mammal needs to be configured, and cannot
    # be:
    def probe():
        inspect(User)._post_inspect

    if create_dependency:
        assert_raises(sa.exc.InvalidRequestError, probe)
    else:
        probe()

    # If we disable configuring mappers while querying, then it succeeds:
    @event.listens_for(
        AnotherBase,
        "before_mapper_configured",
        propagate=True,
        retval=True,
    )
    def disable_configure_mappers(mapper, cls):
        return EXT_SKIP

    probe()

@graph.command(cls=CeleryCommand, context_settings={'allow_extra_args': True})
@click.pass_context
def workers(ctx):
    """Display workers graph."""
    def simplearg(arg):
        return maybe_list(itemgetter(0, 2)(arg.partition(':')))

    def maybe_list(l, sep=','):
        return l[0], l[1].split(sep) if sep in l[1] else l[1]

    args = dict(simplearg(arg) for arg in ctx.args)
    generic = 'generic' in args

    def generic_label(node):
        return '{} ({}://)'.format(type(node).__name__,
                                   node._label.split('://')[0])

    class Node:
        force_label = None
        scheme = {}

        def __init__(self, label, pos=None):
            self._label = label
            self.pos = pos

        def label(self):
            return self._label

        def __str__(self):
            return self.label()

    class Thread(Node):
        scheme = {
            'fillcolor': 'lightcyan4',
            'fontcolor': 'yellow',
            'shape': 'oval',
            'fontsize': 10,
            'width': 0.3,
            'color': 'black',
        }

        def __init__(self, label, **kwargs):
            self.real_label = label
            super().__init__(
                label=f'thr-{next(tids)}',
                pos=0,
            )

    class Formatter(GraphFormatter):

        def label(self, obj):
            return obj and obj.label()

        def node(self, obj):
            scheme = dict(obj.scheme) if obj.pos else obj.scheme
            if isinstance(obj, Thread):
                scheme['label'] = obj.real_label
            return self.draw_node(
                obj, dict(self.node_scheme, **scheme),
            )

        def terminal_node(self, obj):
            return self.draw_node(
                obj, dict(self.term_scheme, **obj.scheme),
            )

        def edge(self, a, b, **attrs):
            if isinstance(a, Thread):
                attrs.update(arrowhead='none', arrowtail='tee')
            return self.draw_edge(a, b, self.edge_scheme, attrs)

    def subscript(n):
        S = {'0': '₀', '1': '₁', '2': '₂', '3': '₃', '4': '₄',
             '5': '₅', '6': '₆', '7': '₇', '8': '₈', '9': '₉'}
        return ''.join([S[i] for i in str(n)])

    class Worker(Node):
        pass

    class Backend(Node):
        scheme = {
            'shape': 'folder',
            'width': 2,
            'height': 1,
            'color': 'black',
            'fillcolor': 'peachpuff3',
        }

        def label(self):
            return generic_label(self) if generic else self._label

    class Broker(Node):
        scheme = {
            'shape': 'circle',
            'fillcolor': 'cadetblue3',
            'color': 'cadetblue4',
            'height': 1,
        }

        def label(self):
            return generic_label(self) if generic else self._label

    from itertools import count
    tids = count(1)
    Wmax = int(args.get('wmax', 4) or 0)
    Tmax = int(args.get('tmax', 3) or 0)

    def maybe_abbr(l, name, max=Wmax):
        size = len(l)
        abbr = max and size > max
        if 'enumerate' in args:
            l = [f'{name}{subscript(i + 1)}'
                 for i, obj in enumerate(l)]
        if abbr:
            l = l[0:max - 1] + [l[size - 1]]
            l[max - 2] = '{}⎨…{}⎬'.format(
                name[0], subscript(size - (max - 1)))
        return l

    app = ctx.obj.app
    try:
        workers = args['nodes']
        threads = args.get('threads') or []
    except KeyError:
        try:
            replies = app.control.inspect().stats() or {}
        except Exception as exc:
            handle_remote_command_error('graph workers', exc)
        workers, threads = [], []
        for worker, reply in replies.items():
            workers.append(worker)
            threads.append(reply['pool']['max-concurrency'])

    wlen = len(workers)
    backend = args.get('backend', app.conf.result_backend)
    threads_for = {}
    workers = maybe_abbr(workers, 'Worker')
    if Wmax and wlen > Wmax:
        threads = threads[0:3] + [threads[-1]]
    for i, threads in enumerate(threads):
        threads_for[workers[i]] = maybe_abbr(
            list(range(int(threads))), 'P', Tmax,
        )

    try:
        broker_uri = args.get('broker', app.connection_for_read().as_uri())
    except Exception as exc:
        handle_remote_command_error('graph workers', exc)
    broker = Broker(broker_uri)
    backend = Backend(backend) if backend else None
    deps = DependencyGraph(formatter=Formatter())
    deps.add_arc(broker)
    if backend:
        deps.add_arc(backend)
    curworker = [0]
    for i, worker in enumerate(workers):
        worker = Worker(worker, pos=i)
        deps.add_arc(worker)
        deps.add_edge(worker, broker)
        if backend:
            deps.add_edge(worker, backend)
        threads = threads_for.get(worker._label)
        if threads:
            for thread in threads:
                thread = Thread(thread)
                deps.add_arc(thread)
                deps.add_edge(thread, worker)

        curworker[0] += 1

    deps.to_dot(sys.stdout)

@sphinxlint_checker(".rst", enabled=False, rst_only=True)
def check_line_too_long_django(file, lines, options=None):
    """A modified version of Sphinx-lint's line-too-long check.

    Original:
    https://github.com/sphinx-contrib/sphinx-lint/blob/main/sphinxlint/checkers.py
    """

    def is_multiline_block_to_exclude(line):
        return _TOCTREE_DIRECTIVE_RE.match(line) or _PARSED_LITERAL_DIRECTIVE_RE.match(
            line
        )

    # Ignore additional blocks from line length checks.
    with mock.patch(
        "sphinxlint.utils.is_multiline_non_rst_block", is_multiline_block_to_exclude
    ):
        lines = hide_non_rst_blocks(lines)

    table_rows = []
    for lno, line in enumerate(lines):
        # Beware, in `line` we have the trailing newline.
        if len(line) - 1 > options.max_line_length:

            # Sphinxlint default exceptions.
            if line.lstrip()[0] in "+|":
                continue  # ignore wide tables
            if _is_long_interpreted_text(line):
                continue  # ignore long interpreted text
            if _starts_with_directive_or_hyperlink(line):
                continue  # ignore directives and hyperlink targets
            if _starts_with_anonymous_hyperlink(line):
                continue  # ignore anonymous hyperlink targets
            if _is_very_long_string_literal(line):
                continue  # ignore a very long literal string

            # Additional exceptions
            try:
                # Ignore headings
                if len(set(lines[lno + 1].strip())) == 1 and len(line) == len(
                    lines[lno + 1]
                ):
                    continue
            except IndexError:
                # End of file
                pass
            if len(set(line.strip())) == 1 and len(line) == len(lines[lno - 1]):
                continue  # Ignore heading underline
            if lno in table_rows:
                continue  # Ignore lines in tables
            if len(set(line.strip())) == 2 and " " in line:
                # Ignore simple tables
                borders = [lno_ for lno_, line_ in enumerate(lines) if line == line_]
                table_rows.extend([n for n in range(min(borders), max(borders))])
                continue
            if _HYPERLINK_DANGLING_RE.match(line):
                continue  # Ignore dangling long links inside a ``_ ref.
            if match := _IS_METHOD_RE.match(line):
                # Ignore second definition of function signature.
                previous_line = lines[lno - 1]
                if previous_line.startswith(".. method:: ") and (
                    previous_line.find(match[1]) != -1
                ):
                    continue
            yield lno + 1, f"Line too long ({len(line) - 1}/{options.max_line_length})"

def _handle_message(self, opcode: int, data: bytes) -> "Optional[Future[None]]":
    """Execute on_message, returning its Future if it is a coroutine."""
    if self.client_terminated:
        return None

    if self._frame_compressed:
        assert self._decompressor is not None
        try:
            data = self._decompressor.decompress(data)
        except _DecompressTooLargeError:
            self.close(1009, "message too big after decompression")
            self._abort()
            return None

    if opcode == 0x1:
        # UTF-8 data
        self._message_bytes_in += len(data)
        try:
            decoded = data.decode("utf-8")
        except UnicodeDecodeError:
            self._abort()
            return None
        return self._run_callback(self.handler.on_message, decoded)
    elif opcode == 0x2:
        # Binary data
        self._message_bytes_in += len(data)
        return self._run_callback(self.handler.on_message, data)
    elif opcode == 0x8:
        # Close
        self.client_terminated = True
        if len(data) >= 2:
            self.close_code = struct.unpack(">H", data[:2])[0]
        if len(data) > 2:
            self.close_reason = to_unicode(data[2:])
        # Echo the received close code, if any (RFC 6455 section 5.5.1).
        self.close(self.close_code)
    elif opcode == 0x9:
        # Ping
        try:
            self._write_frame(True, 0xA, data)
        except StreamClosedError:
            self._abort()
        self._run_callback(self.handler.on_ping, data)
    elif opcode == 0xA:
        # Pong
        self._received_pong = True
        return self._run_callback(self.handler.on_pong, data)
    else:
        self._abort()
    return None

