async def _execute(
    self, transforms: list["OutputTransform"], *args: bytes, **kwargs: bytes
) -> None:
    """Executes this request with the given output transforms."""
    self._transforms = transforms
    try:
        if self.request.method not in self.SUPPORTED_METHODS:
            raise HTTPError(405)

        # If we're not in stream_request_body mode, this is the place where we parse the body.
        if not _has_stream_request_body(self.__class__):
            try:
                self.request._parse_body()
            except httputil.HTTPInputError as e:
                raise HTTPError(400, "Invalid body: %s" % e) from e

        self.path_args = [self.decode_argument(arg) for arg in args]
        self.path_kwargs = {
            k: self.decode_argument(v, name=k) for (k, v) in kwargs.items()
        }
        # If XSRF cookies are turned on, reject form submissions without
        # the proper cookie
        if self.request.method not in (
            "GET",
            "HEAD",
            "OPTIONS",
        ) and self.application.settings.get("xsrf_cookies"):
            self.check_xsrf_cookie()

        result = self.prepare()
        if result is not None:
            result = await result  # type: ignore
        if self._prepared_future is not None:
            # Tell the Application we've finished with prepare()
            # and are ready for the body to arrive.
            future_set_result_unless_cancelled(self._prepared_future, None)
        if self._finished:
            return

        if _has_stream_request_body(self.__class__):
            # In streaming mode request.body is a Future that signals
            # the body has been completely received.  The Future has no
            # result; the data has been passed to self.data_received
            # instead.
            try:
                await self.request._body_future
            except iostream.StreamClosedError:
                return

        method = getattr(self, self.request.method.lower())
        result = method(*self.path_args, **self.path_kwargs)
        if result is not None:
            result = await result
        if self._auto_finish and not self._finished:
            self.finish()
    except Exception as e:
        try:
            self._handle_request_exception(e)
        except Exception:
            app_log.error("Exception in exception handler", exc_info=True)
        finally:
            # Unset result to avoid circular references
            result = None
        if self._prepared_future is not None and not self._prepared_future.done():
            # In case we failed before setting _prepared_future, do it
            # now (to unblock the HTTP server).  Note that this is not
            # in a finally block to avoid GC issues prior to Python 3.4.
            self._prepared_future.set_result(None)

