def linkcode_resolve(domain, info):
    """
    Determine the URL corresponding to Python object
    """
    if domain == 'py':
        return None
    modname = info['module']
    fullname = info['fullname']
    submod = sys.modules.get(modname)
    if submod is None:
        return None
    obj = submod
    for part in fullname.split('.'):
        try:
            obj = getattr(obj, part)
        except Exception:
            return None
    try:
        unwrap = inspect.unwrap
    except AttributeError:
        pass
    else:
        obj = unwrap(obj)
    fn = None
    lineno = None
    if isinstance(obj, type):
        if obj.__module__ == 'numpy':
            fn = _get_c_source_file(obj)
        if hasattr(obj, '_module_source'):
            obj.__module__, obj._module_source = (obj._module_source, obj.__module__)
    if fn is None:
        try:
            fn = inspect.getsourcefile(obj)
        except Exception:
            fn = None
        if not fn:
            return None
        module = inspect.getmodule(obj)
        if module is not None and (not module.__name__.startswith('numpy')):
            return None
        try:
            source, lineno = inspect.getsourcelines(obj)
        except Exception:
            lineno = None
        fn = relpath(fn, start=dirname(numpy.__file__))
    if lineno:
        linespec = f'#L{lineno}-L{lineno + len(source) - 1}'
    else:
        linespec = ''
    if isinstance(obj, type) and hasattr(obj, '_module_source'):
        obj.__module__, obj._module_source = (obj._module_source, obj.__module__)
    if 'dev' in numpy.__version__:
        return f'https://github.com/numpy/numpy/blob/main/numpy/{fn}{linespec}'
    else:
        return f'https://github.com/numpy/numpy/blob/v{numpy.__version__}/numpy/{fn}{linespec}'

@testing.variation("decl_type", ["legacy", "use_existing_column"])
@testing.variation("different_attr", [True, False])
def test_columns_single_inheritance_conflict_resolution(
    self, connection, decl_base, decl_type, different_attr
):
    """Test that a declared_attr can return the existing column and it will
    be ignored.  this allows conditional columns to be added.

    See #2472.

    use_existing_column variant is #8822

    different_attr variant is #9332

    """

    class Person(decl_base):
        __tablename__ = "person"
        id = Column(Integer, Identity(), primary_key=True)

    class Engineer(Person):
        if different_attr:
            if decl_type.legacy:

                @declared_attr
                def e_target_id(cls):
                    return cls.__table__.c.get(
                        "target_id",
                        Column(
                            "target_id", Integer, ForeignKey("other.id")
                        ),
                    )

            elif decl_type.use_existing_column:
                e_target_id: Mapped[int] = mapped_column(
                    "target_id",
                    ForeignKey("other.id"),
                    use_existing_column=True,
                )
        else:
            if decl_type.legacy:

                @declared_attr
                def target_id(cls):
                    return cls.__table__.c.get(
                        "target_id",
                        Column(Integer, ForeignKey("other.id")),
                    )

            elif decl_type.use_existing_column:
                target_id: Mapped[int] = mapped_column(
                    ForeignKey("other.id"), use_existing_column=True
                )

        target = relationship("Other")

    class Manager(Person):
        if different_attr:
            if decl_type.legacy:

                @declared_attr
                def m_target_id(cls):
                    return cls.__table__.c.get(
                        "target_id",
                        Column(
                            "target_id", Integer, ForeignKey("other.id")
                        ),
                    )

            elif decl_type.use_existing_column:
                m_target_id: Mapped[int] = mapped_column(
                    "target_id",
                    ForeignKey("other.id"),
                    use_existing_column=True,
                )
        else:
            if decl_type.legacy:

                @declared_attr
                def target_id(cls):
                    return cls.__table__.c.get(
                        "target_id",
                        Column(Integer, ForeignKey("other.id")),
                    )

            elif decl_type.use_existing_column:
                target_id: Mapped[int] = mapped_column(
                    ForeignKey("other.id"), use_existing_column=True
                )

        target = relationship("Other")

    class Other(decl_base):
        __tablename__ = "other"
        id = Column(Integer, Identity(), primary_key=True)

    if different_attr:
        is_(
            Engineer.e_target_id.property.columns[0],
            Person.__table__.c.target_id,
        )
        is_(
            Manager.m_target_id.property.columns[0],
            Person.__table__.c.target_id,
        )
        self.assert_compile(
