            Person.__table__.c.target_id,
        )
        is_(
            Manager.target_id.property.columns[0],
            Person.__table__.c.target_id,
        )

    # do a brief round trip on this
    decl_base.metadata.create_all(connection)
    with Session(connection) as session:
        o1, o2 = Other(), Other()
        session.add_all(
