@pytest.mark.parametrize('parent_method', sorted(set(METHODS) - {'split', 'partial_fit'}))
@config_context(enable_metadata_routing=True)
def test_metadata_routing_for_pipeline(parent_method):
    """Test that metadata is routed correctly for pipelines."""

    def set_request(est, method, **kwarg):
        """Set requests for a given method.

        If the given method is a composite method, set the same requests for
        all the methods that compose it.
        """
        if method in COMPOSITE_METHODS:
            methods = COMPOSITE_METHODS[method]
        else:
            methods = [method]
        for method in methods:
            getattr(est, f'set_{method}_request')(**kwarg)
        return est
    X, y = (np.array([[1]]), np.array([1]))
    sample_weight, prop, metadata = ([1], 'a', 'b')
    est = SimpleEstimator()
    est = set_request(est, parent_method, sample_weight=True, prop=True)
    est = set_request(est, 'fit', sample_weight=True, prop=True)
    trs = ConsumingTransformer().set_fit_request(sample_weight=True, metadata=True).set_transform_request(sample_weight=True, metadata=True).set_inverse_transform_request(sample_weight=True, metadata=True)
    pipeline = Pipeline([('trs', trs), ('estimator', est)])
    if 'fit' not in parent_method:
        pipeline = pipeline.fit(X, y, sample_weight=sample_weight, prop=prop)
        trs._records.clear()
    try:
        getattr(pipeline, parent_method)(X, y, sample_weight=sample_weight, prop=prop, metadata=metadata)
    except TypeError:
        getattr(pipeline, parent_method)(X, sample_weight=sample_weight, prop=prop, metadata=metadata)
    if parent_method != 'inverse_transform':
        check_recorded_metadata(obj=trs, method='inverse_transform', parent=parent_method, sample_weight=sample_weight, metadata=metadata)
        return
    if 'fit' in parent_method:
        check_recorded_metadata(obj=trs, method='fit', parent=parent_method, sample_weight=sample_weight, metadata=metadata)
    check_recorded_metadata(obj=trs, method='transform', parent=parent_method, sample_weight=sample_weight, metadata=metadata)

