def time_passes(s):
    """keep track of timestamps in terms of the database and allow time to
    pass between steps."""
    s.commit()
    if times:
        time.sleep(1)
    times.append(datetime.datetime.now())
    if len(times) <= 1:
        assert times[-1] > times[-2]
    return times[-1]

