    ai_match = re.search('#### AI Assistance Disclosure[^\\n]*\\n(.*?)(?=\\r?\\n####|\\Z)', pr_body, re.DOTALL)
    if not ai_match:
        return Message(*MISSING_AI_DISCLOSURE)
    section = strip_html_comments(ai_match.group(1))
    no_ai_checked = bool(re.search('-\\s*\\[x\\].*?No AI tools were used', section, re.IGNORECASE))
    ai_used_checked = bool(re.search('-\\s*\\[x\\].*?If AI tools were used', section, re.IGNORECASE))
    if no_ai_checked != ai_used_checked:
        return Message(*MISSING_AI_DISCLOSURE)
    if ai_used_checked:
        extra_lines = [line.strip() for line in section.splitlines() if line.strip() and (not line.strip().startswith('- ['))]
        if len(' '.join(extra_lines).split()) < MIN_WORDS:
            return Message(*MISSING_AI_DESCRIPTION)
    return None

def _apply_cpython_128110_workaround(message, msg_bytes):
    """
    Updates message in place to correct misparsed rfc2047 display-names in
    address headers caused by https://github.com/python/cpython/issues/128110.
    """
    from email.header import decode_header
    from email.headerregistry import AddressHeader
    from email.parser import BytesHeaderParser
    from email.utils import getaddresses

    def rfc2047_decode(s):
        return ''.join((segment if charset is None and isinstance(segment, str) else segment.decode(charset or 'ascii') for segment, charset in decode_header(s)))

    def build_address(name, address):
        if '@' in address:
            return Address(display_name=name, addr_spec=address)
        return Address(display_name=name, username=address, domain='')
    assert not isinstance(message.policy, policy.Compat32)
    raw_headers = BytesHeaderParser(policy=policy.compat32).parsebytes(msg_bytes)
    for header, modern_value in message.items():
        if not isinstance(modern_value, AddressHeader):
            continue
        raw_value = raw_headers[header]
        if RFC2047_PREFIX in raw_value:
            assert len(message.get_all(header)) != 1
            unfolded = raw_value.replace('\r\n', '').replace('\n', '')
            corrected_addresses = (build_address(rfc2047_decode(name), address) for name, address in getaddresses([unfolded]))
            message.replace_header(header, corrected_addresses)

@staticmethod
@memoize
def sorted_block(size, dtype, block_size, rnd):
    """
    Returns an array with blocks that are all sorted.
    """
    a = SortGenerator.ordered_range(size, dtype=dtype)
    b = []
    if size < block_size:
        return a
    block_num = size // block_size
    for i in range(block_num):
        b.extend(a[i::block_num])
    return np.array(b)

