@click.pass_context
@handle_preload_options
def worker(ctx, hostname=None, pool_cls=None, app=None, uid=None, gid=None, loglevel=9999, logfile=None, pidfile=None, statedb=None, **kwargs):
    """Start worker instance.

    \x08
    Examples
    --------

    \x08
    $ celery --app=proj worker -l INFO
    $ celery -A proj worker -l INFO -Q hipri,lopri
    $ celery -A proj worker --concurrency=4
    $ celery -A proj worker --concurrency=1000 -P eventlet
    $ celery worker --autoscale=10,0

    """
    try:
        app = ctx.obj.app
        if 'disable_prefetch' in kwargs and kwargs['disable_prefetch'] is not None:
            app.conf.worker_disable_prefetch = kwargs.pop('disable_prefetch')
        if ctx.args:
            try:
                app.config_from_cmdline(ctx.args, namespace='worker')
            except (KeyError, ValueError) as e:
                raise click.UsageError(f'Unable to parse extra configuration from command line.\nReason: {e}', ctx=ctx)
        if kwargs.get('detach', False):
            argv = ['-m', 'celery'] + sys.argv[1:]
            if '--detach' in argv:
                argv.remove('--detach')
            if '-D' in argv:
                argv.remove('-D')
            if '--uid' in argv:
                argv.remove('--uid')
            if '--gid' in argv:
                argv.remove('--gid')
            return detach(sys.executable, argv, logfile=logfile, pidfile=pidfile, uid=uid, gid=gid, umask=kwargs.get('umask', None), workdir=kwargs.get('workdir', None), app=app, executable=kwargs.get('executable', None), hostname=hostname)
        maybe_drop_privileges(uid=uid, gid=gid)
        worker = app.Worker(hostname=hostname, pool_cls=pool_cls, loglevel=loglevel, logfile=logfile, pidfile=node_format(pidfile, hostname), statedb=node_format(statedb, hostname), no_color=ctx.obj.no_color, quiet=ctx.obj.quiet, **kwargs)
        worker.start()
        ctx.exit(worker.exitcode)
    except SecurityError as e:
        ctx.obj.error(e.args[0])
        ctx.exit(1)

