def _adjust_to_origin(arg_mod, origin, unit):
    """
    Helper function for to_datetime.
    Adjust input argument to the specified origin

    Parameters
    ----------
    arg : list, tuple, ndarray, Series, Index
        date to be adjusted
    origin : 'julian' or Timestamp
        origin offset for the arg
    unit : str
        passed unit from to_datetime, must be 'D'

    Returns
    -------
    DatetimeArray, ndarray, or scalar of adjusted date(s)
    """
    if origin == 'julian':
        original = arg_mod
        j0 = Timestamp(0).to_julian_date()
        if unit != 'D':
            raise ValueError("unit must be 'D' for origin='julian'")
        try:
            arg_mod = arg_mod - j0
        except TypeError as err:
            raise ValueError("incompatible 'arg' type for given 'origin'='julian'") from err
        j_max = Timestamp.max.to_julian_date() - j0
        j_min = Timestamp.min.to_julian_date() - j0
        if np.any(arg_mod > j_max) or np.any(arg_mod < j_min):
            raise OutOfBoundsDatetime(f"{original} is Out of Bounds for origin='julian'")
    else:
        if not ((is_integer(arg_mod) or is_float(arg_mod)) or is_numeric_dtype(np.asarray(arg_mod))):
            raise ValueError(f"'{arg_mod}' is not compatible with origin='{origin}'; it must be numeric with a unit specified")
        try:
            if lib.is_integer(origin) or lib.is_float(origin):
                offset = Timestamp(origin, unit=unit)
            else:
                offset = Timestamp(origin)
        except OutOfBoundsDatetime as err:
            raise OutOfBoundsDatetime(f'origin {origin} is Out of Bounds') from err
        except ValueError as err:
            raise ValueError(f'origin {origin} cannot be converted to a Timestamp') from err
        if offset.tz is not None:
            raise ValueError(f'origin offset {offset} must be tz-naive')
        arg_mod = offset + extract_array(to_timedelta(arg_mod, unit=unit))
    return arg_mod

