@mock.patch(
    "django.test.runner.ParallelTestSuite.initialize_suite",
    side_effect=Exception("initialize_suite() is called."),
)
def test_no_initialize_suite_test_runner(self, *mocked_objects):
    """
    The test suite's initialize_suite() method must always be called when
    using spawn. It cannot rely on a test runner implementation.
    """

    class NoInitializeSuiteTestRunner(DiscoverRunner):
        def setup_test_environment(self, **kwargs):
            return

        def setup_databases(self, **kwargs):
            return

        def run_checks(self, databases):
            return

        def teardown_databases(self, old_config, **kwargs):
            return

        def teardown_test_environment(self, **kwargs):
            return

        def run_suite(self, suite, **kwargs):
            kwargs = self.get_test_runner_kwargs()
            runner = self.test_runner(**kwargs)
            return runner.run(suite)

    with self.assertRaisesMessage(Exception, "initialize_suite() is called."):
        runner = NoInitializeSuiteTestRunner(
            verbosity=0, interactive=False, parallel=2
        )
        runner.run_tests(
            [
                "test_runner_apps.sample.tests_sample.TestDjangoTestCase",
                "test_runner_apps.simple.tests",
            ]
        )

def dedent_initial(s: str, n: int=9999) -> str:
    """Remove indentation from first line of text."""
    return s[n:] if s[:n] == ' ' * n else s

@pytest.mark.filterwarnings("ignore:The default of 'normalize'")
@pytest.mark.filterwarnings('ignore:lbfgs failed to converge')
@pytest.mark.filterwarnings('ignore:A column-vector y was passed when a 1d array.*')
@pytest.mark.parametrize('Regressor', [ARDRegression, BayesianRidge, ElasticNet, ElasticNetCV, GammaRegressor, HuberRegressor, Lars, LarsCV, Lasso, LassoCV, LassoLars, LassoLarsCV, LassoLarsIC, LinearSVR, LinearRegression, OrthogonalMatchingPursuit, OrthogonalMatchingPursuitCV, PassiveAggressiveRegressor, PoissonRegressor, Ridge, RidgeCV, SGDRegressor, TheilSenRegressor, TweedieRegressor])
@pytest.mark.parametrize('ndim', [1, 2])
def test_linear_model_regressor_coef_shape(Regressor, ndim):
    """Check the consistency of linear models `coef` shape."""
    if Regressor is LinearRegression:
        pytest.xfail('LinearRegression does not follow `coef_` shape contract!')
    X, y = make_regression(random_state=0, n_samples=200, n_features=20)
    y = MinMaxScaler().fit_transform(y.reshape(-1, 1))[:, 0] + 1
    y = y[:, np.newaxis] if ndim != 2 else y
    regressor = Regressor()
    set_random_state(regressor)
    regressor.fit(X, y)
    assert regressor.coef_.shape == (X.shape[1],)

